365	func printProposalText(p govflow.ProposalRecord) {
366		fmt.Printf("proposal %s state=%s timelock_end=%d actions=%d\n", p.ID, p.State, p.TimelockEnd, len(p.Actions))
367		for i, action := range p.Actions {
368			fmt.Printf("  action %d: %s\n", i, action)
369		}
370	}
371	
372	func printReceiptText(r *govflow.Receipt, header bool) {
373		if header {
374			fmt.Printf("receipt proposal=%s order=%d executed_at=%d actions=%d\n", r.ProposalID, r.Order, r.ExecutedAt, len(r.Actions))
375		} else {
376			fmt.Printf("executed proposal %s at %d (%d action(s)); receipt order %d\n", r.ProposalID, r.ExecutedAt, len(r.Actions), r.Order)
377		}
378		for _, ar := range r.Actions {
379			fmt.Printf("  action %d: %s\n", ar.Index, ar.Action)
380			fmt.Printf("    treasury:  %d -> %d\n", ar.Treasury.Before, ar.Treasury.After)
381			fmt.Printf("    %s: %d -> %d\n", ar.Recipient.Account, ar.Recipient.Before, ar.Recipient.After)
382		}
383	}
384	
385	func runDemo() {
386		proposal := govflow.Proposal{ID: "gip-7", Title: "fund the audit workstream", State: "voting", Quorum: 1000,
387			TimelockEnd: 5000, Actions: []string{"transfer:audits:25000"}}
388		if err := govflow.Vote(&proposal, 700, true); err != nil {
389			fmt.Println("vote refused:", err)
390		}
391		if err := govflow.Vote(&proposal, 200, false); err != nil {
392			fmt.Println("vote refused:", err)
393		}
394		next := govflow.Tally(&proposal)
395		fmt.Printf("proposal=%s for=%d against=%d quorum=%d next=%s\n", proposal.ID, proposal.ForVotes, proposal.AgainstVotes, proposal.Quorum, next)
396		proposal.State = next
397		proposal.TimelockEnd = 400
398		fmt.Println("executable now:", govflow.Executable([]govflow.Proposal{proposal}, 1000))
399	}
