292		}
293		receipts, err := reopened.Receipts()
294		if err != nil || len(receipts) != 2 {
295			t.Fatalf("receipts after reopen: %v %v", receipts, err)
296		}
297		// 按成功提交先后，而非编号字典序。
298		if receipts[0].ProposalID != "gip-b" || receipts[0].Order != 0 ||
299			receipts[1].ProposalID != "gip-a" || receipts[1].Order != 1 {
