558	func itoa(i int) string {
559		if i == 0 {
560			return "0"
561		}
562		neg := i < 0
563		if neg {
564			i = -i
565		}
566		var buf [20]byte
567		pos := len(buf)
568		for i > 0 {
569			pos--
570			buf[pos] = byte('0' + i%10)
571			i /= 10
572		}
573		if neg {
574			pos--
575			buf[pos] = '-'
576		}
577		return string(buf[pos:])
578	}
