	if p.Tally == nil {
		return nil
	}
	return &TallyResultView{
		ForWeight:     p.Tally.ForWeight,
		AgainstWeight: p.Tally.AgainstWeight,
		Turnout:       p.Tally.ForWeight + p.Tally.AgainstWeight,
		Quorum:        p.Quorum,
		Passed:        p.State == "passed",
		TalliedAt:     p.Tally.TalliedAt,
	}
}

