	mustCreateVote(t, store, in)
	if _, err := store.CastVote("gip-order", "dave", false, 120); err != nil {
		t.Fatal(err)
	}
	if _, err := store.CastVote("gip-order", "alice", true, 130); err != nil {
		t.Fatal(err)
	}
