  "initial_treasury": 100,
  "treasury": 90,
  "balances": {"audits": 10},
  "proposals": {"gip-old": {"id": "gip-old", "state": "passed", "timelock_end": 0, "actions": ["transfer:audits:10"]}},
  "receipts": []
}`
	if err := os.WriteFile(path, []byte(old), 0o600); err != nil {
		t.Fatal(err)
	}
	store, err := Open(path)
	if err != nil {
		t.Fatalf("old file rejected: %v", err)
	}
	defer store.Close()
	p, ok, err := store.Proposal("gip-old")
	if err != nil || !ok || p.State != "passed" {
		t.Fatalf("old proposal: %+v ok=%v err=%v", p, ok, err)
	}
	// 在旧文件上可以新增投票提案（缺省表在首次提交时被正常化）。
	in := baseVoteInput("gip-new")
	mustCreateVote(t, store, in)
	if _, err := store.Execute("gip-old", 0); err != nil {
		t.Fatalf("execute old proposal: %v", err)
	}
}

func TestTamperedVoteStateRejected(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "treasury.json")
	store, err := InitTreasury(path, 1000)
	if err != nil {
		t.Fatal(err)
	}
	in := baseVoteInput("gip-tamper")
	mustCreateVote(t, store, in)
	if _, err := store.CastVote("gip-tamper", "alice", true, 150); err != nil {
		t.Fatal(err)
	}
	if _, err := store.TallyVote("gip-tamper", 200); err != nil {
		t.Fatal(err)
	}
	store.Close()

	good, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	cases := map[string][]byte{
		"ballot weight mismatch": []byte(strings.ReplaceAll(string(good),
			`"representative": "alice",
      "weight": 600`, `"representative": "alice",
      "weight": 601`)),
		"ballot from non-head": []byte(strings.ReplaceAll(string(good),
			`"representative": "alice"`, `"representative": "bob"`)),
		"duplicate ballot rep": []byte(strings.ReplaceAll(string(good),
			`"ballots": [
      {
        "representative": "alice",
        "weight": 600,
        "support": true,
        "voted_at": 150
      }
    ]`, `"ballots": [
      {
        "representative": "alice",
        "weight": 600,
        "support": true,
        "voted_at": 150
      },
      {
        "representative": "alice",
        "weight": 600,
        "support": true,
        "voted_at": 151
      }
    ]`)),
		"tally before deadline": []byte(strings.ReplaceAll(string(good),
			`"tallied_at": 200`, `"tallied_at": 199`)),
		"unknown vote state": []byte(strings.ReplaceAll(string(good),
			`"state": "passed"`, `"state": "approved"`)),
		"id collision": []byte(strings.ReplaceAll(string(good),
			`"proposals": {}`, `"proposals": {"gip-tamper": {"id": "gip-tamper", "state": "passed", "timelock_end": 300, "actions": ["transfer:audits:100"]}}`)),
	}
	for name, raw := range cases {
		t.Run(name, func(t *testing.T) {
			bad := filepath.Join(dir, "bad-"+strings.ReplaceAll(name, " ", "-")+".json")
			if err := os.WriteFile(bad, raw, 0o600); err != nil {
				t.Fatal(err)
			}
			s, err := Open(bad)
			if !errors.Is(err, ErrStateCorrupt) {
				if s != nil {
					s.Close()
				}
				t.Fatalf("Open err=%v, want ErrStateCorrupt", err)
			}
			if got, rerr := os.ReadFile(bad); rerr != nil || string(got) != string(raw) {
				t.Fatalf("corrupt file was modified")
			}
		})
	}
}

